// PhishGuard - traductions (français → anglais).
// Le texte français sert de clé : L.T("texte") renvoie la traduction anglaise si l'anglais est choisi,
// sinon le texte d'origine. L.F("modèle {0}", valeur) fait de même avec string.Format.
// Un texte absent du dictionnaire reste en français (jamais d'erreur).

using System;
using System.Collections.Generic;
using System.Globalization;

namespace PhishGuard
{
    public static class L
    {
        /// <summary>true : interface en anglais.</summary>
        public static bool English;

        /// <summary>« fr », « en » ou « auto » (langue de Windows : français si Windows est en français, sinon anglais).</summary>
        public static void SetLanguage(string lang)
        {
            string l = (lang ?? "").Trim().ToLowerInvariant();
            if (l.StartsWith("en")) English = true;
            else if (l.StartsWith("fr")) English = false;
            else English = CultureInfo.CurrentUICulture.TwoLetterISOLanguageName != "fr";
        }

        public static string T(string fr)
        {
            if (!English || fr == null) return fr;
            string en;
            return En.TryGetValue(fr, out en) ? en : fr;
        }

        public static string F(string fr, params object[] args)
        {
            try { return string.Format(T(fr), args); }
            catch (FormatException) { return string.Format(fr, args); }
        }

        /// <summary>Nombre de traductions (tests).</summary>
        public static int Count { get { return En.Count; } }

