            { "Content-Type", "Content-Type" },
            { "Liste interne de l’équipe sécurité", "Security team internal list" },
            { "Red Flag Domains", "Red Flag Domains" },
            { "Surveillance de vos domaines (sosie apparu récemment)", "Monitoring of your domains (recently appeared look-alike)" },
            { "directeur général", "CEO" },
            { "président", "chair" },
            { "dirigeant", "executive" },
            { "Pression ou urgence", "Pressure or urgency" },
            { "Demande d’identifiants", "Request for credentials" },
